import { invoke } from '@tauri-apps/api/core';
import { logger } from './logger';

/** Header the Python bridge checks against its per-launch BRIDGE_TOKEN. */
export const BRIDGE_TOKEN_HEADER = 'X-Bridge-Token';

let tokenPromise: Promise<string | null> | null = null;

/**
 * The per-launch bridge secret generated by the Tauri backend. Resolves to
 * null outside Tauri (browser dev mode), where the bridge runs unauthenticated.
 */
export function getBridgeToken(): Promise<string | null> {
  if (!tokenPromise) {
    tokenPromise = (async () => {
      if (typeof window === 'undefined' || !('__TAURI_INTERNALS__' in window)) return null;
      try {
        return await invoke<string>('bridge_token');
      } catch (err) {
        logger.error({ err }, 'Failed to obtain bridge token');
        return null;
      }
    })();
  }
  return tokenPromise;
}
